CREATE OR REPLACE VIEW `gulong-chatbot-459723.gulong_reporting.v_cs_sales_funnel_monthly_static`
OPTIONS (
  description = "Static monthly CS sales funnel report layer loaded from the July 2026 funnel CSV. Use for exact Looker parity with the provided Monthly_Funnel extract."
) AS
SELECT
  report_month,
  cs,
  funnel,
  view_scope,
  date_basis,
  SAFE_CAST(inquiries AS INT64) AS inquiries,
  SAFE_CAST(bookings AS INT64) AS bookings,
  net_booking_amount,
  SAFE_CAST(REPLACE(conversion_rate, '%', '') AS FLOAT64) / 100 AS conversion_rate,
  SAFE_CAST(converted_inquiries AS INT64) AS converted_inquiries,
  SAFE_CAST(REPLACE(unique_inquiry_conversion_rate, '%', '') AS FLOAT64) / 100 AS unique_inquiry_conversion_rate,
  SAFE_CAST(canonical_bookings AS INT64) AS canonical_bookings,
  SAFE_CAST(recovered_bookings AS INT64) AS recovered_bookings,
  view_scope = 'operating funnel' AS is_operating_funnel,
  view_scope LIKE '%overlay%' AS is_overlay,
  funnel = 'Calls' AS is_calls
FROM UNNEST([
  STRUCT('July 2026' AS report_month, 'Taira' AS cs, 'Chatbot Handoffs' AS funnel, 'non-additive handoff-origin overlay' AS view_scope, 'inquiry date' AS date_basis, '639' AS inquiries, '24' AS bookings, 'PHP 477,114.14' AS net_booking_amount, '3.76%' AS conversion_rate, '24' AS converted_inquiries, '3.76%' AS unique_inquiry_conversion_rate, '22' AS canonical_bookings, '2' AS recovered_bookings),
  STRUCT('July 2026', 'Taira', 'Sunday Experiment Handoffs', 'non-additive handoff-origin overlay', 'inquiry date', '213', '13', 'PHP 308,547.50', '6.10%', '12', '5.63%', '13', '0'),
  STRUCT('July 2026', 'Rolyn', 'Mixed with Chatbot', 'operating funnel', 'inquiry date', '1811', '18', 'PHP 373,708.83', '0.99%', '18', '0.99%', '18', '0'),
  STRUCT('July 2026', 'Rolyn', 'Pure CS Only', 'operating funnel', 'inquiry date', '887', '7', 'PHP 169,133.04', '0.79%', '7', '0.79%', '7', '0'),
  STRUCT('July 2026', 'Rolyn', 'Calls', 'operating funnel', 'booking date', NULL, '9', 'PHP 313,871.26', NULL, NULL, NULL, '0', '0'),
  STRUCT('July 2026', 'Aira', 'Pure CS Only', 'operating funnel', 'inquiry date', '2825', '30', 'PHP 671,938.20', '1.06%', '29', '1.03%', '30', '0'),
  STRUCT('July 2026', 'Aira', 'Calls', 'operating funnel', 'booking date', NULL, '6', 'PHP 160,459.82', NULL, NULL, NULL, '0', '0'),
  STRUCT('July 2026', 'Remy', 'Pure CS Only', 'operating funnel', 'inquiry date', '2820', '27', 'PHP 548,900.97', '0.96%', '27', '0.96%', '27', '0'),
  STRUCT('July 2026', 'Remy', 'Chatbot Handoff', 'operating funnel', 'inquiry date', '79', '3', 'PHP 108,463.56', '3.80%', '2', '2.53%', '3', '0'),
  STRUCT('July 2026', 'Remy', 'Calls', 'operating funnel', 'booking date', NULL, '4', 'PHP 97,931.79', NULL, NULL, NULL, '0', '0'),
  STRUCT('July 2026', 'Sarah', 'Chatbot Handoff + Sarah Closing', 'operating funnel', 'inquiry date', '755', '33', 'PHP 660,482.90', '4.37%', '33', '4.37%', '31', '2'),
  STRUCT('July 2026', 'Sarah', 'Mixed', 'operating funnel', 'inquiry date', '2203', '24', 'PHP 504,164.84', '1.09%', '23', '1.04%', '23', '1'),
